<script lang="ts">
    import type { Snippet } from "svelte";
	import { isStatusColor } from '../util/color.js';
    import type { StatusColorOrString } from '../util/color.js';
    /**
     * @description
     * A tag is a small piece of information that can be used to categorize or label an item. You can pick between `rounded`, `pill` or `rectangle` shapes. The font size and padding are relative to the parent element by default.
     * Changing the font size without changing the padding will cause padding to be scaled with the font size. This can be changed by setting the `--padding` CSS prop.
     * You can pass a `href` to make the tag a link, or an `onclick` function to make it a button. If you pass a `href`, you can also pass a `target` to specify the target of the link.
     * @cssprop --prefix-padding - The padding of the prefix content. (Default: var(--space-xxs))
     * @cssprop --suffix-padding - The padding of the suffix content. (Default: var(--space-xxs))
     * @cssprop --font-size - The font size of the tag. (Default: 1em)
     * @cssprop --font-weight - The font weight of the tag. (Default: 500)
     * @cssprop --padding - The padding of the tag. (Default: 0.25em 0.5em)
     * @cssprop --vertical-align - The vertical alignment of the tag. (Default: baseline)
     * @example
     * <Tag href="https://google.com" target="_blank" --font-size="1.5rem" color="alert">Tag with a link</Tag>
     * <Tag --padding="0.5em 1em" color="warn" onclick={() => { alert("Hi!"); }}>Warning</Tag>
     * <Tag color="ok">Status OK</Tag>
     * <Tag color="info">Informational</Tag>
     * <p>Here's an inline <Tag code>code tag</Tag> in some text</p>
     */
    let {
        code,
        color = "default",
        shape = "pill",
        scale = "md",
        onclick,
        href,
        target,
        children,
        prefix,
        suffix
    }: { 
        /** Use a mono-spaced font for the tag. */
        code?: boolean;
        /** The color of the tag. */
        color?: StatusColorOrString;
        /** The shape of the tag. */
        shape?: "rounded" | "pill" | "rectangle";
        /** Size variant controlling font-size. Padding scales automatically via em units. */
        scale?: "xs" | "sm" | "md" | "lg" | "xl";
        /** A function to run when the tag is clicked. */
        onclick?: (event: MouseEvent) => void;
        /** A URL to link to. */
        href?: string;
        /** The target of the link. */
        target?: string;
        /** The content of the tag. */
        children: Snippet;
        /** Prefix content, to display before the tag. */
        prefix?: string | Snippet;
        /** Suffix content, to display after the tag. */
        suffix?: string | Snippet;
    } = $props();
    let isSet = $derived(color ? isStatusColor(color) : true);
</script>

{#snippet content()}
    <em>
        {@render children()}
    </em>
{/snippet}

{#snippet _prefix()}
    {#if prefix}
        <span class="Prefix">
            {#if typeof prefix === 'string'}
                {prefix}
            {:else}
                {@render prefix()}
            {/if}
        </span>
    {/if}
{/snippet}

{#snippet _suffix()}
    {#if suffix}
        <span class="Suffix">
            {#if typeof suffix === 'string'}
                {suffix}
            {:else}
                {@render suffix()}
            {/if}
        </span>
    {/if}
{/snippet}

{#if href}
    <a {href} {target} class:code class="Tag Link {shape} {scale}" style="--bgColor: {!isSet ? color : 'var(--status-'+color+'-background)'}; --textColor: {!isSet ? color : 'var(--status-'+color+'-color)'};" onclick={onclick}>
        {@render _prefix()}
        {@render content()}
        {@render _suffix()}
    </a>
{:else if onclick}
    <button type="button" class:code class="Tag {shape} {scale}" style="--bgColor: {!isSet ? color : 'var(--status-'+color+'-background)'}; --textColor: {!isSet ? color : 'var(--status-'+color+'-color)'};" onclick={onclick}>
        {@render _prefix()}
        {@render content()}
        {@render _suffix()}
    </button>
{:else}
    <span class:code class="Tag {shape} {scale}" style="--bgColor: {!isSet ? color : 'var(--status-'+color+'-background)'}; --textColor: {!isSet ? color : 'var(--status-'+color+'-color)'};">
        {@render _prefix()}
        {@render content()}
        {@render _suffix()}
    </span>
{/if}

<style>
    .Tag {
        display: inline-flex;
        align-items: center;
        padding: var(--padding, 0.5em 0.5em);
        font-weight: var(--font-weight, var(--font-weight-normal));
        background: var(--bgColor);
        border-radius: var(--border-radius-base);
        font-size: var(--font-size, 0.85em);
        vertical-align: var(--vertical-align, baseline);
        border: var(--border-size-thin) solid color-mix(in oklch, var(--bgColor) 95%, var(--mix-target, black) 5%);
    }
    .Tag.rectangle {
        border-radius: 0;
    }
    .Tag.pill {
        border-radius: 99999px;
    }
    .Tag.code {
        font-family: var(--font-family-mono);
        padding: var(--padding, 0.15em 0.35em);
        font-size: 1em;
        line-height: 1em;
        background: var(--code-background);
        color: var(--textColor, var(--code-color));
        border: var(--code-border-size) var(--code-border-style) var(--code-border-color);
    }
    em {
        font-style: normal;
        text-box: trim-both cap alphabetic;
    }
    .Prefix {
        padding-inline-end: var(--prefix-padding, var(--space-xxs));
    }
    .Suffix {
        padding-inline-start: var(--suffix-padding, var(--space-xxs));
    }
    a:hover, button:hover {
        background-color: color-mix(in oklch, var(--bgColor) 87%, white 13%);
        cursor: pointer;
    }
    @media (prefers-contrast: more) {
        .Tag {
            border: var(--border-size-thin) solid color-mix(in oklch, var(--bgColor) 50%, var(--mix-target, black) 50%);
        }
        em {
            opacity: 0.99;
        }
    }
    @media (prefers-contrast: less) {
        em {
            opacity: 0.65;
        }
    }

    .Tag.xs { font-size: var(--font-size, 0.65em); }
    .Tag.sm { font-size: var(--font-size, 0.75em); }
    .Tag.lg { font-size: var(--font-size, 1em); }
    .Tag.xl { font-size: var(--font-size, 1.15em); }
</style>